package org.kanger.storage.dumb2;
import java.io.File;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.ContextDependentCutInspection.*;
import org.kanger.ContextDependentIterationInspection.*;
import org.kanger.ContextDependentIterationInspection.Request;
import org.kanger.ContextDependentIterationInspection.Result;
import org.kanger.ContextDependentReplayInspection.Policy;
