public final class ContextDependentIterationRunner {
    private static int checks;
    private interface Attempt{void run()throws Exception;}
    private static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
    private static void reject(Attempt a,String why)throws Exception{boolean no=false;try{a.run();}catch(Exception expected){no=true;}require(no,why);}
    private static Policy policy(){return new Policy(2000000,1000,1000,64000000,200000);}
    private static Request request(int rounds){return new Request(policy(),10000,rounds);}
    private static Mind memory()throws Exception{User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);return m;}
    private static Rule raw(Mind m,String text)throws Exception{return (Rule)m.compileLine(text,false,new LinkedList<ITerm>());}
    private static Member member(Mind m,int id,boolean local)throws Exception{return new Member(m,ContextProductionInventory.inspect(m,new UUID(0,id),3,local,Collections.emptyList(),1000));}
    private static Result inspect(Member x,List<Cut> cuts,int rounds)throws Exception{return ContextDependentIterationInspection.inspect(x,cuts,request(rounds));}
    private static void incomplete(Result r,String why){require(r.status==Status.INCOMPLETE,why);require(r.checked==null&&r.frontier==null&&r.history.isEmpty(),"incomplete iteration exposes no accepted proof/frontier/history prefix");}
    private static void finiteAndOracle()throws Exception{
        Mind empty=memory();Result zero=inspect(member(empty,1,true),Collections.emptyList(),5);require(zero.status==Status.FIXED_POINT&&zero.completedRounds==1&&zero.frontier.common.isEmpty(),"empty supported profile completes one receiving/discovery pass");
        Mind m=memory();raw(m,"!seed(1);");raw(m,"!@x seed(x)->p(x);");raw(m,"!@x p(x)->q(x);");Member x=member(m,2,true);String before=x.inventory.fingerprint;Result chain=inspect(x,Collections.emptyList(),10);require(chain.status==Status.FIXED_POINT&&chain.completedRounds==3,"automatic chain reaches fixed point only after final receiving pass");require(chain.frontier.common.size()==2&&chain.frontier.common.stream().anyMatch(row->row.predicate.equals("q")&&row.sources.size()==3&&row.depth==2),"typed final consequence retains exact whole ancestry and depth");require(chain.history.size()==4&&chain.checked.barriers.size()==4,"baseline and every complete automatic recipe remain auditable");reject(()->chain.history.clear(),"completed history immutable");require(before.equals(ContextProductionInventory.inspect(m,x.inventory.context,3,true,Collections.emptyList(),1000).fingerprint),"finite iteration never writes originals");Result shortRun=inspect(x,Collections.emptyList(),1);incomplete(shortRun,"one changed round is not a fixed point");require(shortRun.completedRounds==1,"productive-pass limit reports completed count without proof prefix");
        for(int model=0;model<8;model++){
            Mind fm=memory();raw(fm,"!a()&&b()->r();");String[] names={"a","b","r"};for(int i=0;i<3;i++)raw(fm,"!"+(((model>>i)&1)==0?"~":"")+names[i]+"();");Result result=inspect(member(fm,10+model,true),Collections.emptyList(),5);boolean a=(model&1)!=0,b=(model&2)!=0,r=(model&4)!=0;require(result.status==((!a||!b||r)?Status.FIXED_POINT:Status.COLLISION),"independent complete Boolean model controls iteration outcome "+model);if(result.status==Status.COLLISION)require(result.completedRounds==0&&result.checked.barriers.get(0).cuts.values().stream().anyMatch(c->!c.originalUnitRefutations.isEmpty()),"original unit refutation stops before productive expansion");
        }
    }
    private static void scopesAndStableCollision()throws Exception{
        Mind xm=memory(),am=memory(),bm=memory();raw(xm,"!@x left(x)&&right(x)->p(x);");raw(am,"!left(1);");raw(am,"!p(1);");raw(bm,"!right(1);");raw(bm,"!~p(1);");Member x=member(xm,21,true),a=member(am,22,false),b=member(bm,23,false);Cut ca=new Cut(null,Collections.singletonList(a)),cb=new Cut(null,Collections.singletonList(b));
        for(boolean reverse:new boolean[]{false,true}){
            Result result=inspect(x,reverse?Arrays.asList(cb,ca):Arrays.asList(ca,cb),5);require(result.status==Status.COLLISION&&result.completedRounds==2,"automatic original counterexample stops at receiving collision before stable verdict");require(result.reason.contains("before stability"),"collision has precedence over unchanged frontier");require(result.checked.barriers.get(2).cuts.get(ca.key).finalUnitRefutations.stream().anyMatch(proof->proof.sources.size()==4),"A refutation retains all three B-production Sources and A's opposite unit");require(!ContextDependentFrontierInspection.compare(ContextDependentFrontierInspection.inspect(result.checked.barriers.get(1),1000000,1000),result.frontier,1000000).changed,"same-frontier collision guard is exercised, not merely growing-frontier rejection");incomplete(inspect(x,Arrays.asList(ca,cb),1),"one round cannot assume future A qualification");
        }
        Mind px=memory(),pa=memory(),pb=memory();raw(px,"!anchor(1);");raw(pa,"!seed(1);");raw(pa,"!@x seed(x)->p(x);");raw(pb,"!~p(1);");Member xx=member(px,31,true),aa=member(pa,32,false),bb=member(pb,33,false);Cut ac=new Cut(null,Collections.singletonList(aa)),bc=new Cut(null,Collections.singletonList(bb));Result privateResult=inspect(xx,Arrays.asList(ac,bc),5);require(privateResult.status==Status.FIXED_POINT&&privateResult.frontier.common.isEmpty(),"independent foreign-only consequences remain private through automatic fixed point");require(privateResult.frontier.pools.get(ac.key).size()==1&&privateResult.frontier.pools.get(bc.key).isEmpty(),"private frontier does not refute sibling negative p");Result trusted=inspect(xx,Collections.singletonList(new Cut("both",Arrays.asList(aa,bb))),5);require(trusted.status==Status.COLLISION&&trusted.completedRounds==0,"whole TRUST original clause plus both physical unit donors refutes at baseline");
        Mind tx=memory(),ta=memory(),tb=memory();raw(tx,"!@x seed(x)->p(x);");raw(ta,"!seed(1);");raw(tb,"!seed(1);");Member qx=member(tx,41,true),qa=member(ta,42,false),qb=member(tb,43,false);Result alternatives=inspect(qx,Collections.singletonList(new Cut("alternatives",Arrays.asList(qb,qa))),5);require(alternatives.status==Status.FIXED_POINT&&alternatives.frontier.common.size()==2,"complete physical proof alternatives survive iteration and fixed-point comparison");
    }
    private static void cyclesAndWitnesses()throws Exception{
        Mind c=memory();raw(c,"!seed(1);");raw(c,"!@x seed(x)->p(x);");raw(c,"!@x p(x)->q(x);");raw(c,"!@x q(x)->p(x);");Result cycle=inspect(member(c,51,true),Collections.emptyList(),10);require(cycle.status==Status.FIXED_POINT&&cycle.completedRounds==5&&cycle.frontier.common.size()==4,"cyclic application growth stops only after Source-superset frontier closes");require(cycle.checked.barriers.get(cycle.checked.barriers.size()-1).common.size()>cycle.frontier.common.size(),"raw proof alternatives and deeper repetitions remain in original-only ledger");require(cycle.frontier.common.stream().filter(row->row.predicate.equals("p")).count()==2,"strict support supersets never disappear during iteration");
        for(int width:new int[]{1,7,17,65}){
            Mind m=memory();StringBuilder prefix=new StringBuilder(),args=new StringBuilder();for(int i=0;i<width;i++){prefix.append("@x").append(i).append(' ');if(i>0)args.append(',');args.append('x').append(i);}Rule seed=raw(m,"!"+prefix+"$u rel("+args+",u);");raw(m,"!"+prefix+"@u rel("+args+",u)->out("+args+",u);");Result result=inspect(member(m,100+width,true),Collections.emptyList(),5);require(result.status==Status.FIXED_POINT&&result.completedRounds==2,"fresh dependent applications alpha-stabilize across automatic rounds");ContextDependentProductionInspection.Row row=result.frontier.common.get(0);require(row.arguments.get(width).symbolSource.rule==seed.getId()&&row.arguments.get(width).arguments.size()==width,"automatic result keeps exact declaration and dependency rank");for(int i=0;i<width;i++)require(row.arguments.get(width).arguments.get(i)==row.arguments.get(i),"automatic dependency coordinate "+i);
        }
        Mind unbounded=memory();raw(unbounded,"!@x $u rel(x,u);");raw(unbounded,"!p(1);");raw(unbounded,"!@a @b rel(a,b)&&p(a)->p(b);");Result growing=inspect(member(unbounded,201,true),Collections.emptyList(),2);incomplete(growing,"nested dependency terms never falsely alpha-stabilize at round bound");require(growing.completedRounds==2,"two productive nested-term passes completed");
    }
    private static void refusals()throws Exception{
        Mind m=memory();raw(m,"!seed(1);");raw(m,"!@x seed(x)->p(x);");Member x=member(m,301,true);incomplete(ContextDependentIterationInspection.inspect(x,Collections.emptyList(),new Request(policy(),1,5)),"finite-state cap refuses without prefix");incomplete(ContextDependentIterationInspection.inspect(x,Collections.emptyList(),new Request(new Policy(2000000,1000,1000,1,200000),10000,5)),"work exhaustion is incomplete");incomplete(ContextDependentIterationInspection.inspect(x,Collections.emptyList(),new Request(new Policy(1,1000,1000,64000000,200000),10000,5)),"whole audit byte exhaustion is incomplete");incomplete(ContextDependentIterationInspection.inspect(x,Collections.emptyList(),new Request(new Policy(2000000,1000,1000,64000000,1),10000,5)),"term arena exhaustion is incomplete");incomplete(ContextDependentIterationInspection.inspect(x,Collections.emptyList(),new Request(new Policy(2000000,1000,1,64000000,200000),10000,1)),"baseline barrier consumes scope allowance; no false fixed point after no-room discovery");
        Mind unsupported=memory();raw(unsupported,"!@x a(x)->b(x)||c(x);");incomplete(inspect(member(unsupported,302,true),Collections.emptyList(),5),"unsupported multiple positive heads never become a fixed point");reject(()->new Request(policy(),10000,0),"zero automatic-round allowance invalid");
        Mind e=memory();Member empty=member(e,303,true);boolean interrupted=false;Thread.currentThread().interrupt();try{inspect(empty,Collections.emptyList(),5);}catch(InterruptedException expected){interrupted=true;require(Thread.currentThread().isInterrupted(),"interruption flag preserved");}finally{Thread.interrupted();}require(interrupted,"cancellation is propagated, not a diagnostic completion");raw(e,"!changed(1);");reject(()->inspect(empty,Collections.emptyList(),5),"stale whole-basis guard throws outside incomplete conversion");
    }
    private static final class Fixture implements AutoCloseable{
        final User user=new User();final DB db=new DB();final Mind root;
        Fixture(Path d,String name)throws Exception{user.setDatabaseDir(d+File.separator);user.setUserDir(Files.createDirectories(d.resolve("operator")).toString());db.init(user);Mind m=new Mind(user);user.setCurrentMind(m);root=(Mind)m.useStorage(name);user.setCurrentMind(root);}
        @Override public void close()throws Exception{if(user.getCurrentMind().isStorageUsed())user.setCurrentMind(user.getCurrentMind().closeStorage());}
    }
    private static void owning()throws Exception{
        Path dir=Files.createTempDirectory("iteration-db-");try(Fixture a=new Fixture(dir,"A")){require(a.root.compile("!left(1); !p(1);",null,false),"A fixture");}try(Fixture b=new Fixture(dir,"B")){require(b.root.compile("!right(1); !~p(1);",null,false),"B fixture");}
        for(boolean reverse:new boolean[]{false,true})try(Fixture f=new Fixture(dir,"X"+reverse)){
            require(f.root.compile("!anchor(1);",null,false),"actual parent");f.db.connectContext(reverse?"B":"A");f.db.connectContext(reverse?"A":"B");long revision=f.db.getRevision();String parent=ContextProductionInventory.inspect(f.root,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint;Mind child=new Mind(f.root);raw(child,"!@x left(x)&&right(x)->p(x);");String before=ContextProductionInventory.inspect(child,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint;
            try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,1000)){
                Result result=lease.iterateDependentRounds(request(5));require(result.status==Status.COLLISION&&result.completedRounds==2,"actual owning automatic cycle finds original collision in both attachment orders");require(result.checked.barriers.get(2).cuts.values().stream().anyMatch(c->c.finalUnitRefutations.stream().anyMatch(proof->proof.sources.size()==4)),"actual independent receiving collision retains all physical Sources");require(f.db.getRevision()==revision&&before.equals(ContextProductionInventory.inspect(child,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint),"automatic lease cycle does not write child or revision");incomplete(lease.iterateDependentRounds(request(1)),"owning limit returns incomplete without proof prefix");raw(child,"!changed(1);");reject(()->lease.iterateDependentRounds(request(5)),"owning whole-child currentness cannot be bypassed by incomplete status");
            }finally{f.root.release(child);}require(parent.equals(ContextProductionInventory.inspect(f.root,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint),"actual parent unchanged after child release");
        }
    }
    public static void main(String[] args){try{System.setProperty("user.home",Files.createTempDirectory("dependent-iteration-").toString());finiteAndOracle();scopesAndStableCollision();cyclesAndWitnesses();refusals();owning();System.out.println("CONTEXT_DEPENDENT_ITERATION_PASS checks="+checks);System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
